// NMEA checksum: XOR of the characters between $ and *
function valid(line) {
  const star = line.indexOf('*');
  if (line[0] !== '$' || star < 0) return false;
  let sum = 0;
  for (let i = 1; i < star; i++) sum ^= line.charCodeAt(i);
  return sum === parseInt(line.slice(star + 1, star + 3), 16);
}
// ddmm.mmmm + N/S/E/W to signed decimal degrees
function degrees(v, hemi) {
  if (!v) return null;
  const n = parseFloat(v), d = Math.floor(n / 100);
  const deg = d + (n - d * 100) / 60;
  return (hemi === 'S' || hemi === 'W') ? -deg : deg;
}

if (!valid(msg.payload)) return null;
// $GPRMC,time,status,lat,N/S,lon,E/W,speed (knots),course,date,...
const f = msg.payload.split('*')[0].split(',');
if (f[2] !== 'A') return null; // A = valid fix, V = no fix yet
const yy = Number(f[9].slice(4, 6));
msg.payload = {
  lat: Number(degrees(f[3], f[4]).toFixed(6)),
  lon: Number(degrees(f[5], f[6]).toFixed(6)),
  speedKmh: Math.round(parseFloat(f[7] || '0') * 1.852 * 10) / 10,
  course: f[8] ? parseFloat(f[8]) : null,
  utc: `${yy < 80 ? 2000 + yy : 1900 + yy}-${f[9].slice(2, 4)}-${f[9].slice(0, 2)}T${f[1].slice(0, 2)}:${f[1].slice(2, 4)}:${f[1].slice(4, 6)}Z`,
};
return msg;

