if (!valid(msg.payload)) return null;
// $GPGGA,time,lat,N/S,lon,E/W,fix quality,satellites,hdop,altitude,M,...
const f = msg.payload.split('*')[0].split(',');
msg.payload = {
  fix: Number(f[6]) > 0,
  satellites: Number(f[7] || 0),
  hdop: f[8] ? parseFloat(f[8]) : null,
  altitudeM: f[9] ? parseFloat(f[9]) : null,
};
return msg;
